fn load_text(path: &str) -> Result<String, PyErr> {
    let mut f = pyrt::catching(|| pyrt::files::open(path, "r"))?;
    let text = pyrt::catching(|| f.read())?;
    f.close();
    Ok(text)
}

fn save_text(path: &str, text: &str) -> Result<(), PyErr> {
    let mut f = pyrt::catching(|| pyrt::files::open(path, "w"))?;
    pyrt::catching(|| f.write(text))?;
    f.close();
    Ok(())
}

fn read_json(path: &str, default: Json) -> Result<Json, PyErr> {
    if !ruai::pyrt::lib::os::path_isfile(path) {
        return Ok(default);
    }
    let raised = 'body: {
        return Ok(pyrt::check!(Json::loads(&pyrt::check!(load_text(path), 'body)).map_err(pyrt::rust_err), 'body));
    };
    match raised {
        caught if caught.is("ValueError") => {
            return Ok(default);
        }
        other => return Err(other),
    }
}

fn write_json(path: &str, data: &Json) -> Result<(), PyErr> {
    let d = ruai::pyrt::lib::os::path_dirname(path);
    if d != "" {
        ruai::pyrt::lib::os::makedirs(&d, true)?;
    }
    save_text(path, &format!("{}\n", data.dumps(Some(2), false)))?;
    Ok(())
}

fn merged(a: &Json, b: &Json) -> Json {
    let mut out = if a.kind() == "dict" { a.copy() } else { Json::new_dict() };
    for k in b.keys() {
        out.set(&k, &b.get(&k));
    }
    out
}

fn stem(path: &str) -> String {
    ruai::pyrt::lib::os::path_splitext(&ruai::pyrt::lib::os::path_basename(path)).0.clone()
}

fn sorted_files(d: &str, suffix: &str) -> Vec<String> {
    if !ruai::pyrt::lib::os::path_isdir(d) {
        return Vec::<String>::new();
    }
    pyrt::sorted(pyrt::py_ok(ruai::pyrt::lib::os::listdir(d)).into_iter().filter_map(|n| if n.ends_with(suffix) { Some(pyrt::files::join(&[d, &n])) } else { None }).collect::<Vec<String>>().into_iter())
}

fn append_event(run_dir: &str, e: &Event) -> Result<(), PyErr> {
    let mut d = Json::new_dict();
    d.set("t", &Json::of_float(pyrt::stdlib::time()));
    d.set("kind", &Json::of_str(&e.kind));
    for (k, v) in [("agent".to_string(), e.agent.clone()), ("node".to_string(), e.node.clone()), ("model".to_string(), e.model.clone()), ("name".to_string(), e.name.clone()), ("detail".to_string(), e.detail.clone()), ("target".to_string(), e.target.clone()), ("task".to_string(), e.task.clone()), ("msg".to_string(), e.msg.clone()), ("src".to_string(), e.src.clone()), ("dst".to_string(), e.dst.clone())] {
        if v != "" {
            d.set(&k, &Json::of_str(&v));
        }
    }
    if e.kind == "node_done" {
        d.set("secs", &Json::of_float(e.secs));
    }
    if e.chars > 0 {
        d.set("chars", &Json::of_int(e.chars));
    }
    if e.kind == "loop" {
        d.set("round", &Json::of_int(e.rounds));
        d.set("max", &Json::of_int(e.limit));
    }
    if e.kind == "llm" {
        d.set("step", &Json::of_int(e.step));
    }
    let mut f = pyrt::catching(|| pyrt::files::open(&pyrt::files::join(&[run_dir, "events.jsonl"]), "a"))?;
    pyrt::catching(|| f.write(&format!("{}\n", d.dumps(None, false))))?;
    f.close();
    Ok(())
}

fn builtins() -> Result<Json, PyErr> {
    Ok(Json::loads(BUILTINS_JSON).map_err(pyrt::rust_err)?)
}

fn edges(graph: &Json) -> Vec<Edge> {
    let mut out: Vec<Edge> = Vec::new();
    for e in graph.get("edges").items() {
        if e.kind() == "list" {
            out.push(Edge { src: e.at(0).text(), dst: e.at(1).text(), when: "".to_string(), limit: 3 });
        } else {
            out.push(Edge { src: e.get("from").text(), dst: e.get("to").text(), when: e.get_str("when", ""), limit: e.get("max").int_or(3) });
        }
    }
    out
}

fn node_agent(name: &str, node: &Json) -> String {
    node.get_str("agent", name)
}

fn dependencies(graph: &Json) -> Result<IndexMap<String, Vec<String>>, PyErr> {
    let mut deps: IndexMap<String, Vec<String>> = IndexMap::new();
    let nodes = graph.get("nodes");
    for n in nodes.keys() {
        deps.insert(n.clone(), Vec::<String>::new());
    }
    for e in edges(graph) {
        if e.when == "" && deps.contains_key(&e.dst) && !pyrt::try_key(&deps, &e.dst)?.contains(&e.src) {
            let arg1 = e.src.clone();
            pyrt::try_key_mut(&mut deps, &e.dst)?.push(arg1);
        }
    }
    for n in nodes.keys() {
        let src = nodes.get(&n).get_str("map", "");
        if src != "" && !pyrt::try_key(&deps, &n)?.contains(&src) {
            pyrt::try_key_mut(&mut deps, &n)?.push(src);
        }
    }
    Ok(deps)
}

fn visit(n: String, path: &[String], deps: &IndexMap<String, Vec<String>>, state: &mut IndexMap<String, i64>, order: &mut Vec<String>) -> Result<(), PyErr> {
    let s = if state.contains_key(&n) { *pyrt::try_key(state, &n)? } else { 0 };
    if s == 1 {
        return Err(PyErr::new(GRAPH_ERROR, &format!("依賴關係有循環: {}(迴圈請用帶 when 的條件邊)", pyrt::concat(path, &vec![n.clone()]).join(" → "))));
    }
    if s == 2 {
        return Ok(());
    }
    state.insert(n.clone(), 1);
    if deps.contains_key(&n) {
        for d in pyrt::try_key(deps, &n)?.iter() {
            visit(d.to_string(), &pyrt::concat(path, &vec![n.clone()]), deps, state, order)?;
        }
    }
    state.insert(n.clone(), 2);
    order.push(n);
    Ok(())
}

fn topo_order(graph: &Json) -> Result<Vec<String>, PyErr> {
    let deps = dependencies(graph)?;
    let mut order: Vec<String> = Vec::new();
    let mut state: IndexMap<String, i64> = IndexMap::new();
    for n in graph.get("nodes").keys() {
        visit(n, &Vec::<String>::new(), &deps, &mut state, &mut order)?;
    }
    Ok(order)
}

fn descendants(graph: &Json, start: String) -> Result<Vec<String>, PyErr> {
    let mut children: IndexMap<String, Vec<String>> = IndexMap::new();
    for (n, ds) in dependencies(graph)?.iter() {
        for d in ds.iter() {
            if !children.contains_key(d) {
                children.insert(d.to_string(), Vec::<String>::new());
            }
            pyrt::try_key_mut(&mut children, d)?.push(n.to_string());
        }
    }
    let mut seen: Vec<String> = Vec::new();
    let mut stack = vec![start];
    while stack.len() as i64 > 0 {
        let x = pyrt::try_pop(&mut stack)?;
        if children.contains_key(&x) {
            for c in pyrt::try_key(&children, &x)?.iter() {
                if !seen.iter().any(|e| *e == c[..]) {
                    seen.push(c.to_string());
                    stack.push(c.to_string());
                }
            }
        }
    }
    Ok(seen)
}

fn validate(graph: &Json, agents: &Json) -> Vec<String> {
    let mut errors: Vec<String> = Vec::new();
    let nodes = graph.get("nodes");
    if nodes.size() == 0 {
        errors.push("graph 沒有任何節點".to_string());
    }
    for n in nodes.keys() {
        let node = nodes.get(&n);
        let agent = node_agent(&n, &node);
        if !agents.has(&agent) {
            errors.push(format!("節點 {}: 未知的 agent '{}'", n, agent));
        }
        let src = node.get_str("map", "");
        if src != "" && !nodes.has(&src) {
            errors.push(format!("節點 {}: map 來源 '{}' 不存在", n, src));
        }
    }
    for e in edges(graph) {
        for (_, v) in [("from".to_string(), e.src.clone()), ("to".to_string(), e.dst.clone())] {
            if !nodes.has(&v) {
                errors.push(format!("邊 {}: 節點 '{}' 不存在", pyrt::s(&e), v));
            }
        }
        if e.when != "" {
            'ok: {
                let raised = 'body: {
                    pyrt::check!(Regex::new(&e.when).map_err(pyrt::rust_err), 'body);
                    break 'ok;
                };
                match raised {
                    ex if ex.is("ValueError") => {
                        errors.push(format!("邊 {}: when 正規表示式錯誤 {}", pyrt::s(&e), pyrt::s(&ex)));
                    }
                    other => pyrt::uncaught(other),
                }
            }
        }
    }
    if errors.len() as i64 == 0 {
        'ok2: {
            let raised = 'body2: {
                pyrt::check!(topo_order(graph), 'body2);
                break 'ok2;
            };
            match raised {
                ex if ex.is("GraphError") => {
                    errors.push(pyrt::str(&ex));
                }
                other => pyrt::uncaught(other),
            }
        }
    }
    errors
}

fn lookup(key: &str, variables: &IndexMap<String, Json>) -> Result<Json, PyErr> {
    let parts = pyrt::split(key, ".");
    if !variables.contains_key(&parts[pyrt::try_idx(0, parts.len())?]) {
        return Ok(Json::null());
    }
    let mut cur = pyrt::try_key(variables, &parts[pyrt::try_idx(0, parts.len())?])?.clone();
    for part in pyrt::slice(&parts, Some(1), None, None) {
        if cur.kind() == "dict" && cur.has(&part) {
            cur = cur.get(&part);
        } else {
            return Ok(Json::null());
        }
    }
    Ok(cur)
}

fn render(template: &str, variables: &IndexMap<String, Json>) -> Result<String, PyErr> {
    let mut out: Vec<String> = Vec::new();
    let mut pos: i64 = 0;
    let template_chars: Vec<char> = template.chars().collect();
    for m in pyrt::re::finditer(r"\{\{\s*([\w.\-]+)\s*\}\}", template) {
        out.push(pyrt::chars_slice(&template_chars, Some(pos), Some(m.start(0)), None));
        let v = lookup(&m.group(1), variables)?;
        if v.is_null() {
            out.push(m.group(0));
        } else if v.kind() == "str" {
            out.push(v.text());
        } else {
            out.push(v.dumps(Some(2), false));
        }
        pos = m.end(0);
    }
    out.push(pyrt::str_slice(template, Some(pos), None, None));
    Ok(out.join(""))
}

fn extract_items(text: String) -> Vec<Json> {
    let mut blocks = pyrt::re::findall(r"(?s)```(?:json)?\s*\n(.*?)```", &text);
    blocks.reverse();
    blocks.push(text.clone());
    'outer: for block in &blocks {
        let mut data: Json;
        'ok: {
            let raised = 'body: {
                data = pyrt::check!(Json::loads(block).map_err(pyrt::rust_err), 'body);
                break 'ok;
            };
            match raised {
                caught if caught.is("ValueError") => {
                    continue 'outer;
                }
                other => pyrt::uncaught(other),
            }
        }
        if data.kind() == "dict" {
            let mut found = Json::null();
            for v in data.items() {
                if v.kind() == "list" {
                    found = v;
                    break;
                }
            }
            data = found;
        }
        if data.kind() == "list" && data.size() > 0 {
            return data.items();
        }
    }
    let items = pyrt::re::findall(r"(?m)^\s*(?:[-*]|\d+[.)])\s+(.+)$", &text);
    items.iter().filter(|&i| pyrt::strip(i) != "").map(|i| Json::of_str(&pyrt::strip(i))).collect::<Vec<Json>>()
}

fn mermaid(graph: &Json) -> String {
    let mut lines = vec!["flowchart TD".to_string()];
    let nodes = graph.get("nodes");
    for n in nodes.keys() {
        let node = nodes.get(&n);
        let label = format!("{}<br/>{}{}", n, node_agent(&n, &node), if node.get_str("map", "") != "" { " ×map".to_string() } else { "".to_string() });
        lines.push(format!("  {}[\"{}\"]", n, label));
    }
    for e in edges(graph) {
        if e.when != "" {
            lines.push(format!("  {} -. \"{} (max {})\" .-> {}", e.src, e.when, e.limit, e.dst));
        } else {
            lines.push(format!("  {} --> {}", e.src, e.dst));
        }
    }
    for n in nodes.keys() {
        let src = nodes.get(&n).get_str("map", "");
        if src != "" {
            lines.push(format!("  {} ==>|items| {}", src, n));
        }
    }
    lines.join("\n")
}

fn describe(graph: &Json) -> Result<String, PyErr> {
    let deps = dependencies(graph).or_raise();
    let mut out: Vec<String> = Vec::new();
    let desc = graph.get_str("description", "");
    if desc != "" {
        out.push(desc);
    }
    let nodes = graph.get("nodes");
    for n in topo_order(graph)? {
        let node = nodes.get(&n);
        let mut extra: Vec<String> = Vec::new();
        if node.get_str("map", "") != "" {
            extra.push(format!("map over {}", node.get_str("map", "")));
        }
        if node.get_str("model", "") != "" {
            extra.push(format!("model={}", node.get_str("model", "")));
        }
        let after = if deps[&n].len() as i64 > 0 { format!("  ← {}", deps[&n].join(", ")) } else { "  (start)".to_string() };
        let ex = if extra.len() as i64 > 0 { format!(" {}", extra.join(" ")) } else { "".to_string() };
        out.push(format!("  [{}] agent={}{}{}", n, node_agent(&n, &node), ex, after));
    }
    for e in edges(graph) {
        if e.when != "" {
            out.push(format!("  ↺ {} → {} when /{}/ (max {})", e.src, e.dst, e.when, e.limit));
        }
    }
    Ok(out.join("\n"))
}

fn color_on() -> bool {
    ruai::pyrt::lib::sys::stdout_isatty() && ruai::pyrt::lib::os::environ_get("NO_COLOR", &None).is_none()
}

fn paint(code: &str, s: String) -> String {
    if color_on() { format!("\u{1b}[{}m{}\u{1b}[0m", code, s) } else { s.clone() }
}

fn dim(s: String) -> String {
    paint("2", s)
}

fn bold(s: String) -> String {
    paint("1", s)
}

fn red(s: String) -> String {
    paint("31", s)
}

fn green(s: String) -> String {
    paint("32", s)
}

fn yellow(s: String) -> String {
    paint("33", s)
}

fn blue(s: String) -> String {
    paint("34", s)
}

fn magenta(s: String) -> String {
    paint("35", s)
}

fn cyan(s: String) -> String {
    paint("36", s)
}

fn out(s: &str, end: &str) {
    print!("{}{}", s, end);
    ruai::pyrt::lib::sys::stdout_flush();
}

fn err(msg: &str) {
    ruai::pyrt::lib::sys::stdout_flush();
    ruai::pyrt::lib::sys::stderr_write(&format!("{}\n", red(format!("錯誤: {}", msg))));
}

fn short(mut text: String, n: i64) -> String {
    text = pyrt::split_ws(&text).join(" ");
    if (text.chars().count() as i64) <= n { text.clone() } else { format!("{}…", pyrt::str_slice(&text, None, Some(n - 1), None)) }
}

fn show_event(e: &Event, verbose: bool) {
    let a = e.agent.clone();
    if e.kind == "node_start" {
        out(&format!("{}{}", cyan(format!("▶ {}", e.node)), dim(format!("  ({} · {})", a, e.model))), "\n");
    } else if e.kind == "node_done" {
        out(&format!("{}{}", green(format!("✔ {}", e.node)), dim(format!("  {:.1}s · {} chars", e.secs, e.chars))), "\n");
        if verbose && e.output != "" {
            out(&dim(e.output.clone()), "\n");
        }
    } else if e.kind == "tool" {
        out(&dim(format!("  ⚙ {}: {} {}", a, e.name, short(e.detail.clone(), 70))), "\n");
    } else if e.kind == "delegate" {
        out(&format!("{}{}", magenta(format!("  ↪ {} → {}: ", a, e.target)), dim(short(e.task.clone(), 70))), "\n");
    } else if e.kind == "delegate_done" {
        out(&format!("{}{}", magenta(format!("  ↩ {} 完成", e.target)), dim(format!("  ({} chars)", e.chars))), "\n");
    } else if e.kind == "loop" {
        out(&yellow(format!("↺ {} → {}  (第 {}/{} 輪)", e.src, e.dst, e.rounds, e.limit)), "\n");
    } else if e.kind == "warn" {
        out(&yellow(format!("! {}", e.msg)), "\n");
    } else if e.kind == "llm" && verbose {
        out(&dim(format!("  … {} 呼叫 {} (step {})", a, e.model, e.step)), "\n");
    }
}

pub fn main() {
    pyrt::init();
    py_main(pyrt::slice(&pyrt::stdlib::argv(), Some(1), None, None));
    pyrt::flush();
}
